from vlb_traj import Session
from VLABench.utils.utils import euler_to_quaternion
import numpy as np

def mul(a,b):
 w,x,y,z=a; W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z, w*X+x*W+y*Z-z*Y, w*Y-x*Z+y*W+z*X, w*Z+x*Y-y*X+z*W])
def inv(q): return np.array([q[0],-q[1],-q[2],-q[3]])
def rot(q,v): return mul(mul(q,np.r_[0.,v]),inv(q))[1:]
def up(q): return rot(q,[0,0,1])
s=Session()
try:
 r=s.skill('pick',target_entity_name='milk',prior_eulers=[[np.pi,0,0]])
 print('PICK',r['stage_success'],r['executed_actions'],flush=True)
 if not r['stage_success']: raise RuntimeError('milk pick failed')
 st=s.state(); obj=np.asarray(st['entities']['milk']['position']); tcp=np.asarray(st['robot']['tcp_position']); qo=np.asarray(st['entities']['milk']['quaternion_wxyz']); qt=np.asarray(st['robot']['tcp_quaternion_wxyz'])
 relq=mul(inv(qt),qo); relp=rot(inv(qt),obj-tcp)
 print('INIT',obj,'up',up(qo),'tcp',tcp,'relp',relp,'relq',relq,flush=True)
 for ang in np.linspace(0,np.pi,7)[1:]:
  qgoal=mul(np.asarray(euler_to_quaternion(ang,0,0)),qo)
  tcpgoal=obj-rot(qgoal,relp); qtgoal=mul(qgoal,inv(relq))
  ik=s.ik(tcpgoal,qtgoal); print('GOAL',ang,ik['success'],tcpgoal,flush=True)
  if not ik['success']: break
  a=np.asarray(s.state()['robot']['joint_positions']); b=np.asarray(ik['joint_positions'])
  for t in np.linspace(0,1,60): s.step(np.r_[a*(1-t)+b*t,[0,0]])
  for _ in range(15): s.step(np.r_[b,[0,0]])
  st=s.state(); oq=np.asarray(st['entities']['milk']['quaternion_wxyz']); op=np.asarray(st['entities']['milk']['position'])
  print('ACTUAL',ang,'pos',op,'up',up(oq),'quat',oq,'grip',st['robot']['gripper_positions'],flush=True)
finally:s.close()
